    "title": "ସପ୍ତମ ଗୋସ୍ୱାମୀ, ଆଧୁନିକ କୃଷ୍ଣଭାବନା ଆନ୍ଦୋଳନର ପଥପ୍ରଦର୍ଶକ",
    "sampradaya": "ବ୍ରହ୍ମ-ମାଧ୍ୱ-ଗୌଡ଼ୀୟ",
