    "title": "ବୃନ୍ଦାବନର ଷଡ୍ ଗୋସ୍ୱାମୀଙ୍କ ମଧ୍ୟରେ ଅଗ୍ରଗଣ୍ୟ",
    "sampradaya": "ବ୍ରହ୍ମ-ମାଧ୍ୱ-ଗୌଡ଼ୀୟ",
