        "p": "ବୃନ୍ଦାବନର କୃଷ୍ଣ ତାଙ୍କ ଐଶ୍ୱର୍ଯ୍ୟମୟ ନାରାୟଣ ରୂପଠାରୁ ଶ୍ରେଷ୍ଠ; ପ୍ରେମ ଶକ୍ତିଠାରୁ ଓ ମାଧୁର୍ଯ୍ୟ ଐଶ୍ୱର୍ଯ୍ୟଠାରୁ ଶ୍ରେଷ୍ଠ; ଏବଂ ଜନ୍ମ ସଂସ୍କାରଠାରୁ ସନ୍ନ୍ୟାସ ପର୍ଯ୍ୟନ୍ତ ପ୍ରତ୍ୟେକ ସ୍ତରରେ ବୈଷ୍ଣବ ଜୀବନ ଶାସ୍ତ୍ର ଦ୍ୱାରା ପରିଚାଳିତ ହେବା ଉଚିତ।"
