    "biography": [
      {
        "p": "ଶ୍ରୀଲ ରଘୁନାଥ ଭଟ୍ଟ ଗୋସ୍ୱାମୀ (1503-1579), କୃଷ୍ଣଲୀଳାରେ ରାଗ-ମଞ୍ଜରୀ, ବାରାଣସୀର ତପନ ମିଶ୍ରଙ୍କ ପୁତ୍ର ଥିଲେ। ପ୍ରଭୁ ତାଙ୍କ ପିତାଙ୍କ ଘରେ ରହିବାବେଳେ ପିଲାଦିନେ ସେ ମହାପ୍ରଭୁଙ୍କ ବାସନ ଧୋଉଥିଲେ ଓ ତାଙ୍କ ପାଦ ଚିପୁଥିଲେ। ପରେ ସେ ପୁରୀରେ ଥରକେ ଆଠ ମାସ ପ୍ରଭୁଙ୍କ ସହ ରହିଲେ, ଏତେ ଦକ୍ଷତାର ସହ ତାଙ୍କ ପାଇଁ ରାନ୍ଧୁଥିଲେ ଯେ ମହାପ୍ରଭୁ ସେ ପ୍ରସ୍ତୁତ କରିଥିବା ସବୁକିଛି ଆସ୍ୱାଦନ କରୁଥିଲେ। ପ୍ରଭୁ ତାଙ୍କୁ ବିବାହ ନ କରିବାକୁ, ତାଙ୍କ ଭକ୍ତ ପିତାମାତାଙ୍କ ସେବା କରିବାକୁ, ଏବଂ ଶେଷରେ ରୂପ ଓ ସନାତନଙ୍କ ତତ୍ତ୍ୱାବଧାନରେ ବୃନ୍ଦାବନ ଯିବାକୁ କହିଲେ। ସେଠାରେ ସେ ତିନି ସ୍ୱରରେ ଶ୍ରୀମଦ୍ ଭାଗବତମ୍ ପାଠ ପାଇଁ ପ୍ରସିଦ୍ଧ ହେଲେ, ଅନେକ ସମୟରେ ଭାବରେ କଣ୍ଠ ରୁଦ୍ଧ ହୋଇଯାଉଥିଲା। ସେ ନିଜ ଶିଷ୍ୟ ରାଜା ମାନ ସିଂହଙ୍କୁ ଗୋବିନ୍ଦଜୀ ମନ୍ଦିର ନିର୍ମାଣ ପାଇଁ ପ୍ରେରଣା ଦେଲେ ଓ ଶ୍ରୀବିଗ୍ରହଙ୍କ ପାଇଁ ଅଳଙ୍କାର ତିଆରି କଲେ। ସେ କେବେ ଗ୍ରାମ୍ୟ ବିଷୟରେ କହୁନଥିଲେ କିମ୍ବା କୌଣସି ବୈଷ୍ଣବଙ୍କ ନିନ୍ଦା ଶୁଣୁନଥିଲେ। ଷଡ୍ ଗୋସ୍ୱାମୀଙ୍କ ମଧ୍ୟରେ କେବଳ ସେ ହିଁ କୌଣସି ଗ୍ରନ୍ଥ ଛାଡ଼ିଯାଇନାହାନ୍ତି। ତାଙ୍କ ସମାଧି ରାଧାକୁଣ୍ଡରେ ଓ ଗୋବିନ୍ଦଜୀ ମନ୍ଦିର ନିକଟରେ ଅଛି।"
      },
      {
        "p": "ବ୍ରଜ ଯିବା ପୂର୍ବରୁ ପ୍ରଭୁଙ୍କ ନିର୍ଦ୍ଦେଶ ଅନୁସାରେ ସେ ବାରାଣସୀରେ ଚାରି ବର୍ଷ ନିଜ ବୃଦ୍ଧ ଭକ୍ତ ପିତାମାତାଙ୍କ ସେବା କଲେ ଏବଂ ଜଣେ ଆତ୍ମଜ୍ଞାନୀ ବୈଷ୍ଣବଙ୍କ ପାଖରେ ଭାଗବତ ଅଧ୍ୟୟନ କଲେ। ପ୍ରଭୁ ତାଙ୍କୁ ନିଜର କଣ୍ଠିମାଳା, ଶ୍ରୀଜଗନ୍ନାଥ ପିନ୍ଧିଥିବା ଚଉଦ ହାତ ଲମ୍ବା ତୁଳସୀ ମାଳା ଓ ପାନ ଦେଲେ, ଯାହାକୁ ସେ ପୂଜା କରି ସ୍ମରଣରେ ଗଳାରେ ପିନ୍ଧୁଥିଲେ। ଅପବିତ୍ର ହେବା ଭୟରେ ଜୀବ ଗୋସ୍ୱାମୀ ତାଙ୍କ ଶରୀରର ଦାହ କରାଇଲେ; ତାଙ୍କ ଭସ୍ମ ରାଧାକୁଣ୍ଡର ତିନି ଗୋସ୍ୱାମୀ ସମାଧିରେ ଓ ଗୋବିନ୍ଦଜୀ ନିକଟ 64 ସମାଧି ଅଞ୍ଚଳରେ ରହିଛି।"
      }
    ],
