    "biography": [
      {
        "p": "ଶ୍ରୀ ଶ୍ରୀନିବାସ ଆଚାର୍ଯ୍ୟ ମହାପ୍ରଭୁଙ୍କ ଆଶୀର୍ବାଦରେ ବଙ୍ଗର ଚାଖନ୍ଦିରେ ଚୈତନ୍ୟ ଦାସ ନାମରେ ପରିଚିତ ଗଙ୍ଗାଧର ଭଟ୍ଟାଚାର୍ଯ୍ୟ ଓ ଲକ୍ଷ୍ମୀପ୍ରିୟାଙ୍କ ପୁତ୍ର ଭାବେ ଜନ୍ମ ହୋଇଥିଲେ, ଏବଂ ତାଙ୍କୁ ପ୍ରଭୁଙ୍କ ଭାବର ମୂର୍ତ୍ତିମନ୍ତ ରୂପ ବୋଲି ବର୍ଣ୍ଣନା କରାଯାଏ (କୃଷ୍ଣଲୀଳାରେ ମଣି-ମଞ୍ଜରୀ)। ସେ ଗୋପାଳ ଭଟ୍ଟ ଗୋସ୍ୱାମୀଙ୍କଠାରୁ ଦୀକ୍ଷା ଓ ଜୀବ ଗୋସ୍ୱାମୀଙ୍କଠାରୁ ଶିକ୍ଷା ପାଇଲେ, ଯିଏ ତାଙ୍କୁ 'ଆଚାର୍ଯ୍ୟ' ଉପାଧି ଦେଲେ। ସେ ଗୌଡ଼ୀୟ ଇତିହାସର ପ୍ରଥମ ଗ୍ରନ୍ଥ ବିତରଣ ଦଳର ନେତୃତ୍ୱ ନେଇ ଗୋସ୍ୱାମୀଙ୍କ ପାଣ୍ଡୁଲିପି ଗୋରୁଗାଡ଼ିରେ ପୂର୍ବକୁ ନେଇଗଲେ। ବନ ବିଷ୍ଣୁପୁର ନିକଟରେ ଗ୍ରନ୍ଥ ଚୋରି ହେବାରୁ ସେ ସେଗୁଡ଼ିକୁ ଫେରାଇ ଆଣିଲେ ଏବଂ ଚୋର ରାଜା ବୀର ହାମ୍ବୀରଙ୍କୁ ଭକ୍ତ କଲେ, ଯିଏ ତାଙ୍କ ଶିଷ୍ୟ ହେଲେ। ସେ ରାମଚନ୍ଦ୍ର କବିରାଜଙ୍କ ପରି ଶିଷ୍ୟଙ୍କ ସହ ବଙ୍ଗସାରା ପ୍ରଚାର କଲେ, କୀର୍ତ୍ତନର 'ମନୋହରଶାହୀ' ଶୈଳୀ ପ୍ରବର୍ତ୍ତନ କଲେ, ଏବଂ ନରୋତ୍ତମ ଓ ଶ୍ୟାମାନନ୍ଦଙ୍କ ସହ ମହାନ ଖେତୁରୀ ଉତ୍ସବର ଆୟୋଜନ କଲେ। ସେ ଷଡ୍ ଗୋସ୍ୱାମୀଙ୍କ ପ୍ରତି ସୁପରିଚିତ ପ୍ରାର୍ଥନା 'ଷଡ୍-ଗୋସ୍ୱାମ୍ୟଷ୍ଟକ' ରଚନା କଲେ।"
      },
      {
        "p": "କାଟୋଆରେ ମହାପ୍ରଭୁଙ୍କ ସନ୍ନ୍ୟାସ ଦେଖି ତାଙ୍କ ପିତା ଗଙ୍ଗାଧର ଏତେ ଅଭିଭୂତ ହେଲେ ଯେ ସେ ଚୈତନ୍ୟ ଦାସ ନାମରେ ପରିଚିତ ହେଲେ, ଏବଂ ପ୍ରଭୁ ଦମ୍ପତିଙ୍କୁ ଏକ ପୁତ୍ରର ଆଶୀର୍ବାଦ ଦେଲେ। ଯୌବନରେ ଶ୍ରୀନିବାସ ନରହରି ସରକାର, ଗଦାଧର ପଣ୍ଡିତ ଓ ଜାହ୍ନବା ଦେବୀଙ୍କୁ ଭେଟିଲେ। 'ପ୍ରେମ-ବିଳାସ' ତାଙ୍କର 117 ଜଣ ଶିଷ୍ୟଙ୍କ ନାମ ଦିଏ, ଯେଉଁଥିରେ ରାମଚନ୍ଦ୍ର କବିରାଜ ଓ ତାଙ୍କ ଭାଇ ଗୋବିନ୍ଦ କବିରାଜ ସାମିଲ। ରାମଚନ୍ଦ୍ରଙ୍କ ସହ ବୃନ୍ଦାବନର ଦ୍ୱିତୀୟ ଯାତ୍ରାରେ ଗୋପାଳ ଭଟ୍ଟ ତାଙ୍କୁ ରାଧାରମଣଙ୍କ ପୂଜା ଗ୍ରହଣ କରିବା ପରିବର୍ତ୍ତେ ବଙ୍ଗରେ ପ୍ରଚାର ଜାରି ରଖିବାକୁ କହିଲେ। ତାଙ୍କ ଅନୁଗାମୀମାନେ ତାଙ୍କ ପ୍ରସ୍ଥାନ ବିଷୟରେ କିଛି ଲେଖି ରଖିନାହାନ୍ତି।"
      }
    ],
