        "p": "ଶିଶୁ ଅବସ୍ଥାରେ ସେ କୃଷ୍ଣଙ୍କୁ ଅର୍ପିତ ହୋଇନଥିବା ଅନ୍ନ ପ୍ରତ୍ୟାଖ୍ୟାନ କରୁଥିଲେ। ବୃନ୍ଦାବନରେ ଦୀକ୍ଷା ପୂର୍ବରୁ ସେ ଦୁଇ ବର୍ଷ ଗୋପନରେ ଲୋକନାଥଙ୍କ ସେବା କଲେ, ଏବଂ ସ୍ୱପ୍ନରେ ରାଧାରାଣୀ ତାଙ୍କୁ କ୍ଷୀର ଫୁଟାଇବାର ନିତ୍ୟ ସେବା ଦେଲେ, ଯାହାର ପୋଡ଼ା ଦାଗ ତାଙ୍କ ହାତରେ ଦେଖାଗଲା। ତାଙ୍କ ଜନ୍ମ ପାଇଁ ତାଙ୍କୁ ବିରୋଧ କରୁଥିବା ଅନେକ ବ୍ରାହ୍ମଣ ତାଙ୍କ ଶିଷ୍ୟ ଗଙ୍ଗାନାରାୟଣ ଚକ୍ରବର୍ତ୍ତୀ ଓ ରାମଚନ୍ଦ୍ର କବିରାଜଙ୍କ ଦ୍ୱାରା ପରାସ୍ତ ହେଲେ, ଏବଂ ରାଜା ନରସିଂହ ଓ ପଣ୍ଡିତ ରୂପନାରାୟଣଙ୍କ ପରି ନେତାମାନେ ତାଙ୍କ ପାଖରେ ଆତ୍ମସମର୍ପଣ କଲେ। 'ପ୍ରେମ-ବିଳାସ' ତାଙ୍କର 123 ଜଣ ଶିଷ୍ୟଙ୍କ ତାଲିକା ଦିଏ।"
