    "shortName": "ବିଶ୍ୱନାଥ ଚକ୍ରବର୍ତ୍ତୀ",
    "title": "17ଶ ଶତାବ୍ଦୀରେ ଗୌଡ଼ୀୟ ସମ୍ପ୍ରଦାୟର ପ୍ରମୁଖ ଆଚାର୍ଯ୍ୟ",
    "sampradaya": "ବ୍ରହ୍ମ-ମାଧ୍ୱ-ଗୌଡ଼ୀୟ",
    "years": "1638 – 1708",
    "appearance": {
      "date": "1638",
      "place": "ନଦୀୟା, ବଙ୍ଗ"
    },
    "disappearance": {
      "date": "1708",
      "place": "ବୃନ୍ଦାବନ"
    },
    "summary": "17ଶ ଶତାବ୍ଦୀର ମହାନ ଆଚାର୍ଯ୍ୟ ଓ ଟୀକାକାର, ଯିଏ ଗୋସ୍ୱାମୀଙ୍କ ଶିକ୍ଷା ରକ୍ଷା କଲେ, 'ଶ୍ରୀ ଗୁର୍ବଷ୍ଟକ' ଲେଖିଲେ ଏବଂ ବଳଦେବ ବିଦ୍ୟାଭୂଷଣଙ୍କୁ ଶିକ୍ଷା ଦେଲେ।",
    "biography": [
      {
        "p": "ଶ୍ରୀଲ ବିଶ୍ୱନାଥ ଚକ୍ରବର୍ତ୍ତୀ ଠାକୁର (1638-1708), କୃଷ୍ଣଲୀଳାରେ ବିନୋଦ-ମଞ୍ଜରୀ, ସେହି ମହାନ ଆଚାର୍ଯ୍ୟ ଯିଏ ଜୀବ ଗୋସ୍ୱାମୀଙ୍କ ପରବର୍ତ୍ତୀ ଶତାବ୍ଦୀରେ ଶ୍ରୀ ଚୈତନ୍ୟଙ୍କ ଶିକ୍ଷାକୁ ରକ୍ଷା କଲେ। ବଙ୍ଗର ଏକ ବ୍ରାହ୍ମଣ ପରିବାରରେ ଜନ୍ମ ହୋଇ ସେ ନରୋତ୍ତମ ଦାସ ଠାକୁରଙ୍କ ପରମ୍ପରାରେ ରାଧାରମଣ ଚକ୍ରବର୍ତ୍ତୀଙ୍କ ଶିଷ୍ୟ ଥିଲେ। ଅଳ୍ପ ବୟସରେ ବିବାହ ହେଲେ ମଧ୍ୟ ସେ ରାଧାକୁଣ୍ଡ ଚାଲିଗଲେ, ଯେଉଁଠି ସେ ରଘୁନାଥ ଦାସ ଗୋସ୍ୱାମୀଙ୍କ କୁଟୀର ପାଖରେ ରହି ଶ୍ରୀ ଗୋକୁଳାନନ୍ଦ ଓ ରଘୁନାଥ ଦାସଙ୍କ ଗୋବର୍ଦ୍ଧନ-ଶିଳାଙ୍କ ପୂଜା କଲେ। ରାଧା-କୃଷ୍ଣଙ୍କ ପରକୀୟା ଭାବକୁ ଅସ୍ୱୀକାର କରୁଥିବା ଲୋକଙ୍କୁ ସେ ପରାସ୍ତ କଲେ। ସେ ଚାଳିଶରୁ ଅଧିକ ଗ୍ରନ୍ଥ ଲେଖିଲେ, ଯେଉଁଥିରେ 'ମାଧୁର୍ଯ୍ୟ-କାଦମ୍ବିନୀ' ଏବଂ ଶ୍ରୀମଦ୍ ଭାଗବତମ୍ ଓ ଭଗବଦ୍ ଗୀତା ଉପରେ ପ୍ରସିଦ୍ଧ ଟୀକା ସାମିଲ, ଯାହା ଶ୍ରୀଲ ପ୍ରଭୁପାଦ ପରାମର୍ଶ କରୁଥିଲେ। ତାଙ୍କ 'ଶ୍ରୀ ଗୁର୍ବଷ୍ଟକ' ଇସ୍କନ୍ ମନ୍ଦିରମାନଙ୍କରେ ପ୍ରତିଦିନ ସକାଳେ ମଙ୍ଗଳ ଆରତିରେ ଗାନ କରାଯାଏ। ବଳଦେବ ବିଦ୍ୟାଭୂଷଣ ତାଙ୍କ ଶିଷ୍ୟ ଥିଲେ। ତାଙ୍କ ସମାଧି ବୃନ୍ଦାବନର ରାଧା-ଗୋକୁଳାନନ୍ଦ ମନ୍ଦିରର ବଗିଚାରେ ଅଛି।"
      },
      {
        "p": "ତାଙ୍କ ପିତା ଥିଲେ ରାମ ନାରାୟଣ ଚକ୍ରବର୍ତ୍ତୀ। ଗୁରୁ ତାଙ୍କୁ ତାଙ୍କ ଯୁବତୀ ପତ୍ନୀଙ୍କ ସହ ଏକ ରାତି ବିତାଇବାକୁ ଆଦେଶ ଦେବାରୁ ସେ ସେହି ରାତି ପବିତ୍ର ନାମ ଜପରେ ବିତାଇଲେ। ହାତରେ ଭାଗବତ ନକଲ କରୁଥିବାବେଳେ ମେଘ ତାଙ୍କୁ ଛାଇ ଦେଲା ଓ ବର୍ଷା ତାଙ୍କୁ ଛୁଇଁଲା ନାହିଁ। ରାଧାକୁଣ୍ଡରେ ତାଙ୍କ ଉପରେ ଆକ୍ରମଣର ଷଡ଼ଯନ୍ତ୍ର କରୁଥିବା ବିରୋଧୀମାନେ ରାଧାରାଣୀଙ୍କ ଜଣେ ଯୁବତୀ ଦାସୀଙ୍କୁ, ଅର୍ଥାତ୍ ତାଙ୍କ ସିଦ୍ଧ ରୂପକୁ ଭେଟିଲେ ଏବଂ ତାଙ୍କ ଅନୁଗାମୀ ହେଲେ। କାମ-ଗାୟତ୍ରୀର ଅକ୍ଷର ବିଷୟରେ ସନ୍ଦେହ ଉଠିବାରୁ ରାଧାରାଣୀ ସ୍ୱପ୍ନରେ ଦେଖାଦେଇ କୃଷ୍ଣଦାସ କବିରାଜଙ୍କ କଥାକୁ ନିଶ୍ଚିତ କଲେ।"
      }
    ],
